const SceneDescriptor* scene_descriptor(u32 id){return id<76?&scenes[id]:nullptr;}
const SceneDescriptor* gameplay_scene(u32 id){return id&&id<76?&scenes[id]:nullptr;}
const SceneDescriptor* scene_for_day(u32 day,u32 within_day){
    if(day>=counts.size()||within_day>=counts[day])return nullptr;
    u32 id=1+within_day;for(u32 i=0;i<day;++i)id+=counts[i];return &scenes[id];
}
